{
  "name": "@motion-studio/export",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "scripts": {
    "build": "tsc -b",
    "typecheck": "tsc -b",
    "lint": "eslint src",
    "test": "vitest run"
  },
  "dependencies": {
    "@motion-studio/shared": "workspace:*"
  },
  "devDependencies": {
    "typescript": "^5.6.3",
    "vitest": "^2.1.4"
  }
}
--- container.ts ---
/**
 * Minimal, hand-rolled subset of Mediabunny's container read/write surface
 * this package actually calls (`docs/13-export/muxer.md`, ADR-012) — kept
 * independent of the real `mediabunny` package so tests can inject a fake
 * without a real browser/WebCodecs environment, matching the DI pattern
 * `packages/audio/src/audio-context.ts` uses for Web Audio and
 * `packages/rendering/src/canvas2d-backend.ts` uses for `CanvasRenderingContext2D`.
 * A real adapter (`new Output(...)`, `new CanvasSource(...)`,
 * `new AudioBufferSource(...)`) satisfies these interfaces structurally —
 * see the API shape confirmed in `muxer.md`.
 */

/** Mediabunny's `CanvasSource`/`VideoSampleSource`: captures a drawable at `add()` time. */
export interface IVideoTrackSource {
  add(timestampSeconds: number, durationSeconds: number): Promise<void>;
}

/** The minimal PCM shape Mediabunny's `AudioBufferSource` (and a real `AudioBuffer`) both satisfy. */
export interface IExportAudioSource {
  readonly duration: number;
  readonly sampleRate: number;
  readonly numberOfChannels: number;
  getChannelData(channel: number): Float32Array;
}

/** Mediabunny's `AudioBufferSource`. */
export interface IAudioTrackSource {
  add(buffer: IExportAudioSource, timestampSeconds: number): Promise<void>;
}

export interface IMuxerOutput {
  addVideoTrack(source: IVideoTrackSource, options: { frameRate: number }): void;
  addAudioTrack(source: IAudioTrackSource): void;
  start(): Promise<void>;
  /** Flushes and closes the container, returning the final file bytes. */
  finalize(): Promise<ArrayBuffer>;
  /** Not every muxer implementation supports aborting mid-write; safe to no-op. */
  cancel?(): Promise<void>;
}

/**
 * Host-supplied factory — only the host has the real canvas/WebCodecs
 * globals to construct a real Mediabunny `Output`/`CanvasSource`/
 * `AudioBufferSource` trio, the same host-owns-the-device split
 * `packages/rendering/src/backend-detection.ts`'s `selectBackend` and
 * `packages/audio/src/audio-engine.ts`'s `attachRealtimeContext` use.
 */
export interface IMuxerFactory {
  createOutput(): IMuxerOutput;
  createVideoTrackSource(): IVideoTrackSource;
  createAudioTrackSource(): IAudioTrackSource;
}
--- codecs.ts ---
/**
 * Codec/container identifiers the Export Engine actually chooses between.
 * Kept local to this package (unlike `ExportPreset`, which lives in
 * `@motion-studio/shared` because it's referenced by the event catalog) —
 * nothing outside Export needs to know a preset's codec makeup, only its id.
 * String values match Mediabunny/WebCodecs' own codec strings
 * (`docs/13-export/muxer.md`'s `canEncodeVideo`/`canEncodeAudio` calls).
 */
export enum VideoCodec {
  H264 = "avc",
  VP9 = "vp9",
}

export enum AudioCodec {
  Opus = "opus",
  AAC = "aac",
}

export enum ContainerFormat {
  MP4 = "mp4",
  WebM = "webm",
}

/**
 * Structurally matches Mediabunny's `canEncodeVideo`/`canEncodeAudio`
 * (`docs/13-export/muxer.md`) — hand-rolled and injected rather than
 * imported so tests can fake capability results without a real browser,
 * matching the DI pattern `packages/audio/src/audio-context.ts` uses for
 * Web Audio.
 */
export interface IEncodeCapabilityProbe {
  canEncodeVideo(codec: VideoCodec): Promise<boolean>;
  canEncodeAudio(codec: AudioCodec): Promise<boolean>;
}

export class UnsupportedCodecError extends Error {
  constructor(kind: "video" | "audio", tried: readonly string[]) {
    super(`No supported ${kind} codec found (tried: ${tried.join(", ")})`);
    this.name = "UnsupportedCodecError";
  }
}

/**
 * `docs/13-export/webcodecs.md`: AAC is confirmed unsupported in Firefox
 * (all platforms) and on desktop Linux generally. Opus is the documented
 * default (CLAUDE.md "Known hard risks" #2); AAC stays an opt-in preset
 * gated by this same capability check, never assumed.
 */
export async function resolveAudioCodec(
  probe: IEncodeCapabilityProbe,
  preferred: AudioCodec,
): Promise<AudioCodec> {
  if (await probe.canEncodeAudio(preferred)) {
    return preferred;
  }
  if (preferred !== AudioCodec.Opus && (await probe.canEncodeAudio(AudioCodec.Opus))) {
    return AudioCodec.Opus;
  }
  throw new UnsupportedCodecError("audio", [preferred, AudioCodec.Opus]);
}

/** H.264 primary, VP9 secondary, per PLAN.md Phase 10's "VideoEncoder wrapper" line. */
export async function resolveVideoCodec(
  probe: IEncodeCapabilityProbe,
  preferred: VideoCodec,
): Promise<VideoCodec> {
  if (await probe.canEncodeVideo(preferred)) {
    return preferred;
  }
  const fallback = preferred === VideoCodec.H264 ? VideoCodec.VP9 : VideoCodec.H264;
  if (await probe.canEncodeVideo(fallback)) {
    return fallback;
  }
  throw new UnsupportedCodecError("video", [preferred, fallback]);
}

