  console.log(text);
  const buttons = await page.$$eval("button", (els) => els.map((e) => e.textContent?.trim() || e.getAttribute("aria-label") || e.title));
  console.log("=== BUTTONS ===");
  console.log(JSON.stringify(buttons, null, 2));
  await page.screenshot({ path: "/tmp/studio-screenshot.png", fullPage: true });
  await browser.close();
})();
